    if (nArg2 != 0 && pArg3 == 0)  // 有状态无参数 → 归零
        newState = 0;                    // 有状态无参数 → 归零（防御式）

    int oldState = this[50];  // this+200〔主状态(0自由/1硬直/2冻结)〕
    this[50] = newState;                 // +200 主状态
