                        int obj = (*(int(__thiscall**)(int*, int))(*this + 772))(this, i);  // 结果 = 虚调用 vt+772
                        (*(void(__thiscall**)(int, int))(*(int*)obj + 36))(obj, 0);  // vt+36 恢复
