    sub_41A170();  // sub_41A170 —— 登记表整体重置（遍历元素 + 清空 deque）

    if (toModule == 3 || toModule == 4 || toModule == 6)  // 判定 toModule == 3 或 toModule == 4 或 toModule == 6
        g_77F488 = 0;                     // 战斗类模块 → 标志 0
    else
        g_77F488 = 1;

