        *(int*)(this + 284) = *(int*)(*(int*)(this + 36) + 12);  // 写字段 this+284（bBindGate284） ← *(int*)(*(int*)(this + 36) + 12)
        sub_46D300(*(int*)(this + 16));  // sub_46D300 —— 选角界面复位与资源释放
