            sub_43BEE0(*(void**)((char*)addr_8F8528 + 28), (int)sub_422E70(1249),  // sub_43BEE0 —— 【播报上屏】；sub_422E70 —— 存 CStringManager::getStr 取本地化串
                       -6567706, 0, -1);
